import React, { useEffect, useState } from "react";

export default function App() {
  return (
    <div style= { styles.container } >
    <WeatherCard />
    </div>
  );
}

function WeatherCard() {
  const [weather, setWeather] = useState(null);
  const [city, setCity] = useState("Cairo");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // 🔑 ضع API KEY مجاني من WeatherAPI.com (خطة مجانية 100%)
  const API_KEY = "PASTE_YOUR_FREE_API_KEY_HERE";

  const fetchWeather = async () => {
    if (!API_KEY || API_KEY === "PASTE_YOUR_FREE_API_KEY_HERE") {
      setError("Add your API key first");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const res = await fetch(
        `https://api.weatherapi.com/v1/current.json?key=${API_KEY}&q=${city}&aqi=no`
      );

      const data = await res.json();

      if (data.error) {
        setError(data.error.message);
        setWeather(null);
      } else {
        setWeather({
          city: data.location.name,
          country: data.location.country,
          temp: data.current.temp_c,
          condition: data.current.condition.text,
          icon: data.current.condition.icon,
          wind: data.current.wind_kph,
          humidity: data.current.humidity,
        });
      }
    } catch (err) {
      setError("Network error");
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchWeather();
  }, []);

  return (
    <div style= { styles.card } >
    <div style={ styles.search }>
      <input
          value={ city }
  onChange = {(e) => setCity(e.target.value)
}
placeholder = "Enter city..."
style = { styles.input }
  />
  <button onClick={ fetchWeather } style = { styles.button } >
    Search
    </button>
    </div>

{ loading && <div style={ styles.loader }> </div> }

{ error && <p style={ styles.error }> { error } </p> }

{
  weather && (
    <div style={ styles.content }>
      <h2>
      { weather.city }, { weather.country }
      </h2>

      < img
  src = { weather.icon }
  alt = "weather"
  style = {{ width: "80px" }
}
          />

  < h1 > { Math.round(weather.temp) }°C </h1>
    < p > { weather.condition } </p>

    < div style = { styles.details } >
      <div>💧 { weather.humidity }% </div>
        <div>🌬 { weather.wind } km / h </div>
          </div>
          </div>
      )}
</div>
  );
}

const styles = {
  container: {
    height: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "linear-gradient(135deg, #020617, #0f172a)",
  },

  card: {
    width: "350px",
    padding: "25px",
    borderRadius: "25px",
    background: "rgba(255,255,255,0.08)",
    backdropFilter: "blur(20px)",
    color: "white",
    boxShadow: "0 25px 60px rgba(0,0,0,0.6)",
    textAlign: "center",
  },

  search: {
    display: "flex",
    gap: "10px",
    marginBottom: "20px",
  },

  input: {
    flex: 1,
    padding: "10px",
    borderRadius: "12px",
    border: "none",
    outline: "none",
  },

  button: {
    padding: "10px 15px",
    borderRadius: "12px",
    border: "none",
    cursor: "pointer",
    background: "#38bdf8",
    color: "white",
    fontWeight: "bold",
  },

  content: {
    marginTop: "10px",
  },

  details: {
    display: "flex",
    justifyContent: "space-around",
    marginTop: "15px",
    fontSize: "14px",
  },

  error: {
    color: "#f87171",
    marginTop: "10px",
  },

  loader: {
    margin: "20px auto",
    width: "30px",
    height: "30px",
    border: "4px solid rgba(255,255,255,0.3)",
    borderTop: "4px solid white",
    borderRadius: "50%",
    animation: "spin 1s linear infinite",
  },
};

const styleSheet = document.styleSheets[0];
styleSheet.insertRule(`
@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
`, styleSheet.cssRules.length);
